sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.submitted = false;
    c.submitting = false;

    c.form = {
        full_name: '',
        email: '',
        phone: '',
        years_experience: '',
        education_level: 'Bachelors',
        skills: '',
        certifications: '',
        relevant_projects: '',
        resume: '',
        consent: false
    };

    c.submitApplication = function() {

        if (!c.form.consent) {
            alert('Please accept the consent.');
            return;
        }

        c.submitting = true;

        c.server.get({

            action: 'submit_application',

            requisition_id: c.data.req_id,

            full_name: c.form.full_name,
            email: c.form.email,
            phone: c.form.phone,

            years_experience: c.form.years_experience,
            education_level: c.form.education_level,

            skills: c.form.skills,
            certifications: c.form.certifications,
            relevant_projects: c.form.relevant_projects,

            resume: c.form.resume

        }).then(function(response) {

            c.submitting = false;

            if (response.data.success) {

                c.submitted = true;
                c.appNumber = response.data.app_number;

                window.location.href =
                    "?id=aegis_my_apps&application_id=" +
                    response.data.app_number;

            } else {

                alert(
                    'Application submission failed.\n' +
                    (response.data.error || '')
                );

            }

        }, function(error) {

            c.submitting = false;

            console.log(error);

            alert('Unexpected error occurred.');

        });

    };

};

sp_widget.css:
.aegis-apply {
    max-width: 900px;
    margin: 40px auto;
    padding: 0 20px;
}

.apply-card {
    background: #ffffff;
    border-radius: 24px;
    padding: 40px;
    box-shadow: 0 8px 24px rgba(0,0,0,0.08);
}

.form-section {
    margin-bottom: 32px;
}

.form-section h4 {
    font-size: 14px;
    font-weight: 700;
    color: #0f3b2f;
    margin-bottom: 20px;
}

.form-row {
    display: flex;
    gap: 20px;
    margin-bottom: 18px;
}

.form-row .form-group {
    flex: 1;
}

.form-group {
    margin-bottom: 18px;
}

.form-group label {
    display: block;
    margin-bottom: 8px;
    font-weight: 600;
    color: #1f2937;
}

.form-control {
    width: 100%;
    height: 48px;
    border: 1px solid #d8d2c2;
    border-radius: 14px;
    padding: 0 14px;
    font-size: 14px;
    background: #f9f7f1;
    box-sizing: border-box;
}

textarea.form-control {
    height: 220px;
    padding: 14px;
    resize: vertical;
}

.consent-box {
    background: #f9f7f1;
    border-radius: 16px;
    padding: 16px;
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.aegis-btn-primary {
    width: 100%;
    height: 54px;
    border: none;
    border-radius: 999px;
    background: #e16b4d;
    color: white;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
}

.aegis-btn-primary:hover {
    opacity: 0.95;
}

sp_widget.script:
(function() {

    data.req_id = $sp.getParameter('requisition_id') || '';
    data.role_title = 'Position';

    if (data.req_id) {

        var reqGr = new GlideRecord(
            'x_snc_aegis_job_requisition'
        );

        if (reqGr.get(data.req_id)) {

            data.role_title =
                reqGr.getValue('role_title');
        }
    }

    if (input &&
        input.action == 'submit_application') {

        try {

            var candidateId = '';

            var candGr =
                new GlideRecord(
                    'x_snc_aegis_candidate'
                );

            candGr.addQuery(
                'email',
                input.email
            );

            candGr.query();

            if (candGr.next()) {

                candidateId =
                    candGr.getUniqueValue();

                candGr.setValue(
                    'skills',
                    input.skills
                );

                candGr.setValue(
                    'years_experience',
                    input.years_experience
                );

                candGr.setValue(
                    'education_level',
                    input.education_level
                );

                candGr.setValue(
                    'certifications',
                    input.certifications
                );

                candGr.setValue(
                    'relevant_projects',
                    input.relevant_projects
                );

                candGr.update();

            } else {

                candGr.initialize();

                candGr.setValue(
                    'full_name',
                    input.full_name
                );

                candGr.setValue(
                    'email',
                    input.email
                );

                candGr.setValue(
                    'phone',
                    input.phone
                );

                candGr.setValue(
                    'skills',
                    input.skills
                );

                candGr.setValue(
                    'years_experience',
                    input.years_experience
                );

                candGr.setValue(
                    'education_level',
                    input.education_level
                );

                candGr.setValue(
                    'certifications',
                    input.certifications
                );

                candGr.setValue(
                    'relevant_projects',
                    input.relevant_projects
                );

                candGr.setValue(
                    'consent_status',
                    'GRANTED'
                );

                candidateId =
                    candGr.insert();
            }

            var appGr =
                new GlideRecord(
                    'x_snc_aegis_application'
                );

            appGr.initialize();

            appGr.setValue(
                'candidate',
                candidateId
            );

            appGr.setValue(
                'requisition',
                input.requisition_id
            );

            appGr.setValue(
                'stage',
                'APPLIED'
            );

            appGr.setValue(
                'screening_status',
                'PENDING'
            );

            appGr.setValue(
                'resume',
                input.resume
            );

            var appId =
                appGr.insert();

            var appNumber =
                appId;

            var appRecord =
                new GlideRecord(
                    'x_snc_aegis_application'
                );

            if (appRecord.get(appId)) {

                appNumber =
                    appRecord.getValue('number');
            }

            data.success = true;
            data.app_number = appNumber;

            gs.info(
                '[AEGIS] Application Created: ' +
                appNumber
            );

        } catch (ex) {

            data.success = false;
            data.error = ex.toString();

            gs.error(
                '[AEGIS] Error: ' +
                ex.toString()
            );
        }
    }

})();
